\label{th3.1}
Let $0<p<\infty$ and $\alpha>-2$. If $t\ge \frac{1}{p}$ and 
	\begin{align*}
	\sup_{u,a\in\mathbb{D}}\frac{(1-|u|^2)^t}{(|1-|\varphi_a(u)|^2)^\frac{1}{p}}\left(  \int_{\mathbb{D}}\frac{(1-|z|^2)^\alpha(1-|\varphi_a(z)|^2)}{|1-\overline{u}\varphi(z)|^{\alpha+2+pt}}dA(z) \right)^\frac{1}{p}<\infty,
\end{align*}
then $C_\varphi$ is a bounded operator on $AT_p^\infty(\alpha)$.

\cite[Lemma 2.5]{of2}\label{le2.5}
	For \(s > - 1,r,t\geq0\) and \(r + t - s>2\), we have
\begin{flalign*}
\quad \quad  &\int_{\mathbb{D}}\frac{(1-\vert\xi\vert^{2})^{s}}{\vert1-\overline{\xi}z\vert^{r}\vert1-\overline{\xi}w\vert^{t}}\mathrm{d}A(\xi)&&
\end{flalign*}	
	\begin{equation*}
	\lesssim\left\{ 
	\begin{aligned}
		&\frac{1}{\vert1-\overline{z}w\vert^{r + t - s - 2}},& \text{if }&r - s,t - s < 2\\
		&\frac{1}{(1-\vert z\vert^{2})^{r - s - 2}\vert1-\overline{z}w\vert^{t}},& \text{if }&t - s < 2<r - s\\
		&\frac{1}{(1-\vert z\vert^{2})^{r - s - 2}\vert1-\overline{z}w\vert^{t}}+\frac{1}{(1-\vert w\vert^{2})^{t - s - 2}\vert1-\overline{z}w\vert^{r}},& \text{if }&r - s,t - s>2.
	\end{aligned}
	\right.
	\end{equation*}

Let   $\varphi(z)=\overline{w}z$. It is easy to check that $\varphi:\mathbb{D} \to \mathbb{D}$ is analytic. Using Lemma \ref{th3.1}, if 
	\begin{align*}
		\sup_{u,a\in\mathbb{D}}\frac{(1-|u|^2)^t}{(|1-|\varphi_a(u)|^2)^\frac{1}{p}}\left(  \int_{\mathbb{D}}\frac{(1-|z|^2)^\alpha(1-|\varphi_a(z)|^2)}{|1-\overline{u}\varphi(z)|^{\alpha+2+pt}}dA(z) \right)^\frac{1}{p}<\infty,
	\end{align*}
	we obtain
	\begin{align*}
		&\sup_{a\in\mathbb{D}}\int_{\mathbb{D}}\frac{(1-|a|^2)^t}{|1-\overline{a}z|^{t+1}}|f(\varphi(z))|^{p}(1-|z|^{2})^{\alpha+1}dA(z)\\
		\lesssim&  \sup_{a\in\mathbb{D}}\int_{\mathbb{D}}\frac{(1-|a|^2)^t}{|1-\overline{a}z|^{t+1}}|f(z)|^{p}(1-|z|^{2})^{\alpha+1}dA(z).
	\end{align*}
	Therefore, by Lemma \ref{alp},
	\[
	\sup_{a\in\mathbb{D}}\int_{\mathbb{D}}\frac{(1-|a|^2)^t}{|1-\overline{a}z|^{t+1}}|f(\overline{w}z)|^{p}(1-|z|^{2})^{\alpha+1}dA(z)\lesssim \|f\|_{AT_p^\infty(\alpha)}^p.
	\]
	So, we only need to prove that
	\begin{align*}
		\sup_{u,a\in\mathbb{D}}\frac{(1-|u|^2)^t}{(|1-|\varphi_a(u)|^2)^\frac{1}{p}}\left(  \int_{\mathbb{D}}\frac{(1-|z|^2)^\alpha(1-|\varphi_a(z)|^2)}{|1-\overline{u}\varphi(z)|^{\alpha+2+pt}}dA(z) \right)^\frac{1}{p}<\infty.
	\end{align*}
	Using Lemma \ref{le2.5}, we get
	\begin{align*}
		&\sup_{u,a\in\mathbb{D}}\frac{(1-|u|^2)^t}{(|1-|\varphi_a(u)|^2)^\frac{1}{p}}\left(  \int_{\mathbb{D}}\frac{(1-|z|^2)^\alpha(1-|\varphi_a(z)|^2)}{|1-\overline{u}\varphi(z)|^{\alpha+2+pt}}dA(z) \right)^\frac{1}{p}\\
		=&\sup_{u,a\in\mathbb{D}}\frac{(1-|u|^2)^t|1-\overline{a}u|^{\frac{2}{p}}}{(1-|a|^2)^\frac{1}{p}(1-|u|^2)^{\frac{1}{p}}}\left( \int_{\mathbb{D}}  \frac{(1-|a|^2)(1-|z|^2)^{\alpha+1}}{|1-\overline{a}z|^2|1-\overline{uw}z|^{\alpha+2+pt}} dA(z)\right)^\frac{1}{p}\\
		=&\sup_{u,a\in\mathbb{D}}(1-|u|^2)^{t-\frac{1}{p}}|1-\overline{a}u|^{\frac{2}{p}}\left( \int_{\mathbb{D}}  \frac{(1-|z|^2)^{\alpha+1}}{|1-\overline{a}z|^2|1-\overline{uw}z|^{\alpha+2+pt}} dA(z)\right)^\frac{1}{p}\\
		\lesssim &\sup_{u,a\in\mathbb{D}}\frac{(1-|u|^2)^{t-\frac{1}{p}}|1-\overline{a}u|^{\frac{2}{p}}}{(1-|uw|^2)^{t-\frac{1}{p}}
|1-\overline{a}uw|^{\frac{2}{p}}}<\infty,
	\end{align*}
as desired.  Here we used the assumption that  $\alpha>-1$ and $t> \frac{1}{p}$. 	The proof is complete.

