\cite[Lemma 2.7]{ylh}
Let $0<p<\infty$, $\alpha>-2$, $n\in\mathbb N \cup \{0\}$ and $f\in AT_p^\infty(\alpha)$. Then 
$$
|f^{(n)}(z)|\lesssim\frac{\|f\|_{AT_p^\infty(\alpha)}}{(1-|z|^2)^{\frac{\alpha+2}{p}+n}}
$$
for all $z\in\mathbb{D}$.

Let $1\le p,q<\infty$, $\alpha,\beta>-2$ and \(f\in AT_q^\infty(\beta)\). Then
	\begin{enumerate}
		\item [(i)] If $1-\frac{\beta+2}{q}<0$, then \(\mathfrak{D}_{f}\in\mathscr{B}(AT_p^\infty(\alpha))\) for any  $  p<\frac{\alpha+2}{\frac{\beta+2}{q}-1}$.
		
		\item [(ii)] If $1-\frac{\beta+2}{q}\ge0$, then \(\mathfrak{D}_{f}\in\mathscr{B}(AT_p^\infty(\alpha))\) for all $p\ge1$. 
		
	\end{enumerate}

\label{le2.4}
Suppose \(r>0\), \(0 \leq c<s<\infty\) and \(\mu\) is a finite positive Borel measure on $[0, 1)$. Then the following statements are equivalent:

\begin{enumerate}
\item [(i)] \(\mu\) is a \(s\)-Carleson measure;
	
\item [(ii)]
\[\sup _{b \in \mathbb{D}} \int_{0}^{1} \frac{(1-|b|)^{r}}{(1-t)^{c}(1-|b| t)^{s+r-c}} d \mu(t)<\infty;\]
	
\item [(iii)]
\[\sup _{b \in \mathbb{D}} \int_{0}^{1} \frac{(1-|b|)^{r}}{(1-t)^{c}|1-b t|^{s+r-c}} d \mu(t)<\infty.\]
\end{enumerate}

\label{le4.2}
	Suppose \(r>0\), \(0 \leq c<s<\infty\) and \(\mu\) is a finite positive Borel measure on $[0, 1)$. Then the following statements are equivalent:
	\begin{enumerate}
		\item [(i)] \(\mu\) is a vanishing \(s\)-Carleson measure;
		
		\item [(ii)] 
		\[\lim _{ |b| \to 1^- } \int_{0}^{1} \frac{(1-|b|)^{r}}{(1-t)^{c}(1-|b| t)^{s+r-c}} d \mu(t)=0;\]
		
		\item [(iii)]
		\[\lim _{ |b| \to 1^- } \int_{0}^{1} \frac{(1-|b|)^{r}}{(1-t)^{c}|1-b t|^{s+r-c}} d \mu(t)=0.\]
	\end{enumerate}

\cite[Proposition 3.1]{zlt}\label{le2.2}
Let \(w, a \in \mathbb{D}\). For \(r>0\) and \(t>0\), let 
\[I_{w, a}=\int_{0}^{2 \pi} \frac{1}{\left|1-\overline{w} e^{i \theta}\right|^{t}\left|1-\overline{a} e^{i \theta}\right|^{r}} d \theta. \]
Then the following results hold:

\begin{enumerate}
                                                   
  
                                                                               
  
                                                                                                           
  
                              
                                                                                        
  
                             
                                                                                   
  
                              
                                                                  

	
\item [(i)] When \(t > 1\) and \(r > 1\), 
\[I_{w, a} \asymp \frac{1}{(1-|w|^{2})^{t-1}|1-w \bar{a}|^{r}}+\frac{1}{(1-|a|^{2})^{r-1}|1-w \bar{a}|^{t}}.\]
	
\item [(ii)] When \(t > 1 = r\), 
\[ I_{w,a} \asymp \frac{1}{(1 - |w|^2)^{t - 1} |1 - \overline{w}a|} + \frac{1}{|1 - \overline{w}a|^t} \log \frac{e}{1 - |\varphi_w(a)|^2}. \] 
\end{enumerate}

\cite[Lemma 2.2]{zgsl}\label{le2.3}
Let \(\delta>-1\), \(c>0\), \(0 \leq \rho<1\). Then 
\[\int_{0}^{1} \frac{(1-r)^{\delta}}{(1-\rho r)^{\delta+c+1}} d r \asymp \frac{1}{(1-\rho)^{c}}.\]
